mapper.select:
select
a.id, a.position_id, a.student_id, a.semester_id, a.apply_remark, a.status, a.reject_reason,
a.audit_time, a.audit_user, a.create_time, a.update_time, a.create_user, a.update_user,
p.name as position_name,
p.dept_id as dept_id,
s.name as student_name,
s.student_no as student_no
from position_apply a
left join position p on a.position_id = p.id
left join student s on a.student_id = s.id


